import{_ as t,o,c as n,a2 as a}from"./chunks/framework.D9E58p8B.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"title":"Troubleshooting"},"headers":[],"relativePath":"en/guide/depannage.md","filePath":"en/guide/depannage.md"}'),r={name:"en/guide/depannage.md"};function d(i,e,s,c,h,l){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="start-with-daimon-doctor" tabindex="-1">Start with <code>daimon_doctor</code> <a class="header-anchor" href="#start-with-daimon-doctor" aria-label="Permalink to &quot;Start with `daimon_doctor`&quot;">​</a></h2><p>Ask your AI to call <a href="/Daimon/en/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>. It is a read-only diagnostic, with no parameters, that cannot bring up a dialog. It returns:</p><table tabindex="0"><thead><tr><th>Key</th><th>What it tells you</th></tr></thead><tbody><tr><td><code>ok</code></td><td>Overall verdict</td></tr><tr><td><code>responsible_app</code></td><td>The application macOS ties the permissions to</td></tr><tr><td><code>permissions</code></td><td>Screen Recording and Accessibility: granted or not</td></tr><tr><td><code>consequences</code></td><td>What each missing permission does to each tool</td></tr><tr><td><code>exclusions</code></td><td>State of the exclusions file</td></tr><tr><td><code>ceiling</code></td><td>Active ceiling</td></tr><tr><td><code>cannot_detect</code></td><td>What the diagnostic cannot detect</td></tr><tr><td><code>next</code></td><td>Suggested next steps</td></tr></tbody></table><p>Read <code>cannot_detect</code>: the absence of a reported problem is not proof for what is listed there.</p><h2 id="symptoms" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Lead</th></tr></thead><tbody><tr><td>Screenshots fail (macOS)</td><td><strong>Screen Recording</strong> permission missing for the responsible application: see <a href="./autorisations.html">Permissions</a></td></tr><tr><td><code>main_type</code>, <code>main_key</code>, <code>main_hover</code> or <code>main_navigate</code> return <code>done</code> with no effect</td><td><strong>Accessibility</strong> permission missing</td></tr><tr><td><code>main_click</code>, <code>main_press</code> or <code>main_drag</code> wait a long time</td><td>Without Accessibility, they wait 30 seconds for a confirmation dialog</td></tr><tr><td>An action is refused</td><td>The ceiling is too low for this tool: call <a href="/Daimon/en/reference/diagnostic.html#main-ceiling"><code>main_ceiling</code></a>, and adjust the panel slider if you wish</td></tr><tr><td>A screenshot is refused</td><td>An application listed in <code>exclusions.yaml</code> is in the foreground, or the file is broken: check the <code>exclusions</code> key of <code>daimon_doctor</code></td></tr><tr><td>The Overlay markers do not appear</td><td>The tools answer <code>ok</code> even with no overlay window; turn on <strong>Présence à l&#39;écran</strong> (On-screen presence) in the panel, then read the <code>overlay</code> key of <a href="/Daimon/en/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> (<code>listening</code>, <code>last_log_line</code>); the markers appear in no screenshot, by design</td></tr><tr><td>Your client does not see Daimon</td><td>Restart the client; check with <code>Daimon status</code>; Daimon must be installed before registering; <code>Daimon install</code> rewrites the entry: see <a href="./clients-mcp.html">AI clients</a></td></tr><tr><td>SmartScreen warns (Windows)</td><td>Warning despite the Authenticode signature (publisher ArboRithm): <strong>More info</strong>, then <strong>Run anyway</strong></td></tr><tr><td>The icon cannot be found (Windows)</td><td>Look in the notification area, possibly in the overflow menu</td></tr></tbody></table><h2 id="permissions-granted-but-nothing-changes" tabindex="-1">Permissions granted, but nothing changes <a class="header-anchor" href="#permissions-granted-but-nothing-changes" aria-label="Permalink to &quot;Permissions granted, but nothing changes&quot;">​</a></h2><p>macOS ties them to the application that launches Daimon. Grant them to the one that <code>responsible_app</code> names.</p><h2 id="reporting-a-problem" tabindex="-1">Reporting a problem <a class="header-anchor" href="#reporting-a-problem" aria-label="Permalink to &quot;Reporting a problem&quot;">​</a></h2><p><a href="https://github.com/ArboRithm/Daimon/issues" target="_blank" rel="noreferrer">Open an issue</a> or write to <a href="mailto:app@arborithm.fr" target="_blank" rel="noreferrer">app@arborithm.fr</a>.</p>',11)])])}const g=t(r,[["render",d]]);export{p as __pageData,g as default};
